corrected_code:
import { NextRequest, NextResponse } from 'next/server';
import { currentUser } from '@clerk/nextjs/server';
import { prisma } from '@/lib/prisma';

export async function DELETE(
  req: NextRequest,
  context: { params: { endpointId: string } }
) {
  const user = await currentUser();
  if (!user) {
    return NextResponse.json({ error: 'Authentication required' }, { status: 401 });
  }

  const { endpointId } = context.params;
  const endpoint = await prisma.webhookEndpoint.findFirst({
    where: { id: endpointId, ownerId: user.id }
  });
  if (!endpoint) {
    return NextResponse.json({ error: 'Webhook endpoint not found or unauthorized' }, { status: 404 });
  }

  await prisma.webhookEndpoint.delete({
    where: { id: endpointId }
  });

  return NextResponse.json({ success: true, deletedId: endpointId });
}
